package ai.xzkj.recruitment.resumes;
import jakarta.validation.constraints.*;import java.time.Instant;import java.util.UUID;
record ResumeIntakeCreateRequest(@NotBlank@Size(max=120)String reference,@NotBlank@Size(max=120)String displayLabel,Instant receivedAt){}
record ResumeIntakeReviewRequest(@NotNull ResumeIntakeStatus decision,@Size(max=500)String note){}
record ResumeIntakeResponse(UUID id,UUID contactId,UUID companyId,String companyName,String candidateName,String jobTitle,String accountName,ResumeIntakeSource source,String anonymousKey,String displayLabel,ResumeIntakeStatus status,String processingStatus,String documentType,boolean malwareScanned,String extractedTextDigestPrefix,String failureCode,String failureReason,Instant processedAt,String analysisStatus,String analysisFailureCode,String analysisFailureReason,Instant analysisCompletedAt,UUID sourceActionTaskId,Instant receivedAt,String reviewedBy,Instant reviewedAt,String reviewNote,Instant createdAt){static ResumeIntakeResponse from(ResumeIntake item){var contact=item.getContact();var company=contact.getCandidate().getCompany();return new ResumeIntakeResponse(item.getId(),contact.getId(),company.getId(),company.getName(),contact.getCandidate().getDisplayName(),contact.getJobPosition().getTitle(),contact.getBossAccount().getDisplayName(),item.getSource(),item.getResumeDigest().substring(0,12),item.getDisplayLabel(),item.getStatus(),item.getProcessingStatus(),item.getDocumentType(),item.isMalwareScanned(),item.getExtractedTextDigest()==null?null:item.getExtractedTextDigest().substring(0,12),item.getFailureCode(),item.getFailureReason(),item.getProcessedAt(),item.getAnalysisStatus(),item.getAnalysisFailureCode(),item.getAnalysisFailureReason(),item.getAnalysisCompletedAt(),item.getSourceActionTaskId(),item.getReceivedAt(),item.getReviewedBy()==null?null:item.getReviewedBy().getDisplayName(),item.getReviewedAt(),item.getReviewNote(),item.getCreatedAt());}}
